'use client';

/**
 * North Indian Vedic Chart React Display Component
 * Mounts and renders pure SVG vector geometry generated by NorthIndianChartRenderer.
 */

import React, { useEffect, useRef } from 'react';
import { ChartData, ChartOptions } from './types';
import { NorthIndianChartRenderer } from './NorthIndianChartRenderer';

export interface NorthIndianChartProps {
  data: ChartData;
  options?: ChartOptions;
  className?: string;
}

export const NorthIndianChart: React.FC<NorthIndianChartProps> = ({
  data,
  options = {},
  className = '',
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const rendererRef = useRef<NorthIndianChartRenderer | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    // Instantiate or update renderer
    if (!rendererRef.current) {
      rendererRef.current = new NorthIndianChartRenderer(data, options);
    } else {
      rendererRef.current.setData(data);
      rendererRef.current.setOptions(options);
    }

    // Render directly into the container DOM node
    rendererRef.current.renderToElement(containerRef.current);
  }, [data, options]);

  return (
    <div
      className={`relative w-full max-w-[580px] aspect-square mx-auto bg-white border border-[#E8E2D6] rounded-xl shadow-xs p-3 select-none ${className}`}
    >
      <div
        ref={containerRef}
        className="w-full h-full flex items-center justify-center"
      />
    </div>
  );
};
